/* Décors des 20 scènes */
const etoilesCiel = (g, n, h = 400) => { const r = aleaScene(g); let s = ''; for (let i = 0; i < n; i++) s += `<circle cx="${(r() * 800).toFixed(0)}" cy="${(r() * h).toFixed(0)}" r="${(.8 + r() * 1.800).toFixed(1)}" fill="#fff" opacity="${(.5 + r() * .5).toFixed(2)}"/>`; return s; };
const tableNappe = (c = '#fbf6ee', bord = '#e2d6c6') => `<path d="M60 390H740L770 470H30Z" fill="${c}"/><path d="M30 470H770V500H30Z" fill="${bord}"/><path d="M30 500Q120 520 200 500T400 500T600 500T770 500" fill="${bord}"/>`;
const guirlandeFete = () => `<path d="M0 30Q200 90 400 40T800 40" stroke="#8a7a6a" stroke-width="2" fill="none"/>${[...Array(14).keys()].map((i) => { const x = 30 + i * 56, y = 46 + 18 * Math.sin(i * .9); return `<path d="M${x - 14} ${y}L${x + 14} ${y}L${x} ${y + 26}Z" fill="${['#e5566b', '#f2c14e', '#5e89c2', '#8e73b9'][i % 4]}"/>`; }).join('')}`;

