  soustlamer: (u) => `<defs>${degrade(`${u}a`, ['#4fb0d8', '#1f6a9a', '#0f3a6a'])}</defs><rect width="800" height="600" fill="url(#${u}a)"/>${[100, 300, 520].map((x) => `<path d="M${x} 0L${x - 60} 600H${x + 30}Z" fill="#fff" opacity=".07"/>`).join('')}<path d="M0 500Q200 470 400 500T800 490V600H0Z" fill="#e6d2a8"/>${etoilesCiel(91, 26, 480).replace(/fill="#fff"/g, 'fill="#cfefff"')}`,
  verger: (u) => fondDehors(u, ['#a6d8f0', '#f2f6e4'], ['#8fc06a', '#6aa04f'], `${[[150, '#e5566b'], [330, '#c9d660'], [490, '#c9283a'], [660, '#7a4a8a']].map(([x, c]) => `<g transform="translate(${x} 260) scale(1.05)">${fruitArbre(c, 6)}</g>`).join('')}`),
