  roshhashana: (u) => fondInterieur(u, ['#f6e8d0', '#ecd8b6'], ['#a8774a', '#8a5f3c'], `${[...Array(10).keys()].map((i) => `<path d="M${60 + i * 76} ${60 + (i % 3) * 40}q10-14 20 0q-10 14-20 0Z" fill="${['#e2905a', '#c9604a', '#e2b03a'][i % 3]}" opacity=".6"/>`).join('')}`) + tableNappe('#fbf6ee', '#e2c99a'),
